from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [float('inf')] * n
    dist[s] = 0
    queue = deque([s])

    while queue:
        u = queue.popleft()
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                queue.append(v)

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
```

