import heapq

def solve(n, edges, s, t):
    """
    Finds the length of the shortest path from node s to node t in a directed weighted graph.

    Args:
        n: The number of nodes in the graph (0 to n-1).
        edges: A list of (u, v, w) tuples, each representing a directed edge from u to v with weight w.
        s: The starting node.
        t: The target node.

    Returns:
        The minimum total weight of a path from s to t, or 0 if s equals t, or -1 if t cannot be reached from s.
    """
    if s == t:
        return 0

    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = {i: float('inf') for i in range(n)}
    dist[s] = 0
    pq = [(0, s)]  # (distance, node)

    while pq:
        d, u = heapq.heappop(pq)

        if d > dist[u]:
            continue

        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
